functions.body:
block([m,n,L,r,p,st,pv,a,prev],
 m:length(M), n:length(M[1]), L:makelist(makelist(M[i,j],j,1,n),i,1,m), r:1, st:[], pv:[], prev:L,
 for j:1 thru n do if r<=m then (
  p:0,
  for i:r thru m do if L[i][j]#0 then (if p=0 then p:i else if abs(L[i][j])<abs(L[p][j]) then p:i),
  if p>0 then (
   if p#r then L:makelist(if i=p then L[r] elseif i=r then L[p] else L[i],i,1,m),
   L:makelist(if i=r then rowNorm(L[r]) else L[i],i,1,m), a:L[r][j],
   L:makelist(if i=r or L[i][j]=0 then L[i] else rowNorm(a*L[i]-L[i][j]*L[r]),i,1,m),
   pv:endcons(j,pv), r:r+1,
   if L#prev then st:endcons(apply(matrix,L),st), prev:L)),
 L:makelist(if lead(L[i])=0 then L[i] else L[i]/lead(L[i]),i,1,m),
 if L#prev then st:endcons(apply(matrix,L),st),
 [st,pv])

prts.feedbackvariables:
if listp(ans1) then an1:ans1 else (if listp(listify(ans1)) then an1:listify(ans1) else an1:[ans1]);
if listp(ans2) then an2:ans2 else (if listp(listify(ans2)) then an2:listify(ans2) else an2:[ans2]);

varlist1: listofvars(an1);
varlist2: listofvars(an2);
goodvars: is((varlist1=[x] or varlist1=[]) and (varlist2 = [x] or varlist2 = []));

deglqn(pol):= is(hipow(pol,x)<n);
gooddegs: is(alltrue(deglqn,an1) and alltrue(deglqn,an2));

validInput: goodvars and gooddegs;


ansIm: if (validInput) then map(polyToVect,an1) else [];
ansKer: if (validInput) then map(polyToVect,an2) else [];

indIm: not dependentvects(ansIm);
inspanIm: alltrue(inImT,ansIm);
spansIm: is(inspanIm and rank(matrify(ansIm))=dimImT);

indKer: not dependentvects(ansKer);
inspanKer: alltrue(inKerT,ansKer);
spansKer: is(inspanKer and rank(matrify(ansKer))=dimKerT);

goodIm: indIm and spansIm;
goodKer: indKer and spansKer;
allgood: is(goodIm and goodKer);
